fn segment_json(segment:&PathSegment,baseline:f64,italic:bool,rotation:f32,center:[f32;2])->Result<String,String>{let map=|point:[f64;2]|{let x=point[0]-if italic{(point[1]-baseline)*0.22}else{0.0};let y=point[1];let(sin,cos)=f64::from(rotation).sin_cos();[f64::from(center[0])+(x-f64::from(center[0]))*cos-(y-f64::from(center[1]))*sin,f64::from(center[1])+(x-f64::from(center[0]))*sin+(y-f64::from(center[1]))*cos]};let value=match segment{PathSegment::Move{to}=>json!({"kind":"move","to":map(*to)}),PathSegment::Line{to}=>json!({"kind":"line","to":map(*to)}),PathSegment::Quad{ctrl,to}=>json!({"kind":"quad","ctrl":map(*ctrl),"to":map(*to)}),PathSegment::Cubic{ctrl1,ctrl2,to}=>json!({"kind":"cubic","ctrl1":map(*ctrl1),"ctrl2":map(*ctrl2),"to":map(*to)}),PathSegment::Close=>json!({"kind":"close"}),_=>return Err("layout-render-outline-not-resolved".into())};serde_json::to_string(&value).map_err(|e|e.to_string())}

